const inside=(root,value)=>{const r=path.relative(root,value);return r===''||(!r.startsWith('..'+path.sep)&&r!=='..'&&!path.isAbsolute(r));};
if(inside(sourceRoot,workRoot)||inside(workRoot,sourceRoot))throw Error('Source and mutable work must be separate sibling directories.');
