const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const out=path.join(workRoot,'output'),tmp=path.join(workRoot,'tmp'),directory=path.join(workRoot,'workspace'),app=path.join(sourceRoot,COMPONENT);
await fs.mkdir(sourceRoot,{recursive:true,mode:0o700});await fs.mkdir(workRoot,{recursive:true,mode:0o700});
for(const name of [sourceRoot,workRoot])need((await fs.realpath(name))===name,'Use an explicit canonical directory: '+name);
