 need((await fs.readdir(out)).length===0&&(await fs.readdir(tmp)).length===0,'A new receiving operation requires empty output and temporary directories.');
 const id=options.operation??'fiscaldata-public-'+crypto.randomUUID();
 need(/^[A-Za-z0-9][A-Za-z0-9._-]{0,95}$/.test(id),'Use a short plain operation ID.');
 operation={schema:'fiscaldata-public-receiving.v1',id,applicationRef:APPLICATION_REF,repository:REPOSITORY,sourceRoot,workRoot,startedAt:new Date().toISOString(),stages:[]};
 await atomicJson(operationFile,operation);
